-- Baseline schema (design doc §3.4, §4.2). This is migration 0001; every later
-- change is a new db/migrations/NNNN_*.sql file applied by app/codeclash/migrate.py
-- — do NOT edit this file to add columns, add a migration instead.
-- Idempotent so the first rollout is safe on a database that already has these
-- objects (e.g. an already-provisioned prod).

DO $$ BEGIN CREATE TYPE match_state AS ENUM ('WAITING', 'ACTIVE', 'FINISHED');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE match_outcome AS ENUM ('WIN', 'DRAW', 'FORFEIT', 'VOID');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN CREATE TYPE verdict AS ENUM ('PENDING', 'AC', 'WA', 'TLE', 'MLE', 'RE', 'CE');
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

CREATE TABLE IF NOT EXISTS users (
    id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    username      TEXT NOT NULL UNIQUE,
    email         TEXT NOT NULL UNIQUE,
    password_hash TEXT NOT NULL,
    rating        INTEGER NOT NULL DEFAULT 1200,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS problems (
    id              BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    slug            TEXT NOT NULL UNIQUE, -- test cases live at testcases/<slug>/
    title           TEXT NOT NULL,
    statement_md    TEXT NOT NULL, -- pre-rendered statement HTML (pandoc; name kept for compat)
    band            SMALLINT NOT NULL CHECK (band BETWEEN 1 AND 3), -- coarse label / rating seed
    time_limit_ms   INTEGER NOT NULL DEFAULT 2000,
    memory_limit_kb INTEGER NOT NULL DEFAULT 262144,
    created_at      TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS matches (
    id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    player_a    BIGINT NOT NULL REFERENCES users(id),
    player_b    BIGINT NOT NULL REFERENCES users(id),
    problem_id  BIGINT NOT NULL REFERENCES problems(id),
    state       match_state NOT NULL DEFAULT 'WAITING',
    outcome     match_outcome,
    winner_id   BIGINT REFERENCES users(id),
    created_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
    started_at  TIMESTAMPTZ,
    finished_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS submissions (
    id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
    match_id     UUID REFERENCES matches(id), -- NULL = practice submission
    user_id      BIGINT NOT NULL REFERENCES users(id),
    problem_id   BIGINT NOT NULL REFERENCES problems(id),
    language     TEXT NOT NULL DEFAULT 'python',
    code         TEXT NOT NULL,
    verdict      verdict NOT NULL DEFAULT 'PENDING',
    tests_passed INTEGER NOT NULL DEFAULT 0,
    tests_total  INTEGER,
    submitted_at TIMESTAMPTZ NOT NULL DEFAULT now(), -- fair-win rule key (§4.2)
    judged_at    TIMESTAMPTZ
);

CREATE INDEX IF NOT EXISTS submissions_match_idx ON submissions (match_id, user_id, submitted_at);

-- Admission control (§3.2): one in-flight submission per player per duel.
CREATE UNIQUE INDEX IF NOT EXISTS submissions_one_inflight
    ON submissions (match_id, user_id) WHERE verdict = 'PENDING';

-- Per-duel append-only event log; seq gives the per-duel total order (§4.2).
CREATE TABLE IF NOT EXISTS duel_events (
    match_id   UUID NOT NULL REFERENCES matches(id),
    seq        INTEGER NOT NULL,
    type       TEXT NOT NULL,
    payload    JSONB NOT NULL DEFAULT '{}',
    created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (match_id, seq)
);

CREATE TABLE IF NOT EXISTS rating_history (
    id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id       BIGINT NOT NULL REFERENCES users(id),
    match_id      UUID NOT NULL REFERENCES matches(id),
    rating_before INTEGER NOT NULL,
    rating_after  INTEGER NOT NULL,
    created_at    TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS rating_history_user_idx ON rating_history (user_id, created_at);

-- Unseen-problem pick during matchmaking (§4.1); Redis holds the hot copy.
CREATE TABLE IF NOT EXISTS seen_problems (
    user_id    BIGINT NOT NULL REFERENCES users(id),
    problem_id BIGINT NOT NULL REFERENCES problems(id),
    seen_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
    PRIMARY KEY (user_id, problem_id)
);
